def zone_fees(areas_km: dict[str, float]) -> dict[str, int]:
    fees = {}
    for area, distance_m in areas_km.items():
        zone = zone_of(area)
        if zone == "X":
            fees[area] = -1
        else:
            if distance_m <= BASE_METRES:
                fees[area] = BASE_FEE_KES
            else:
                extra_km = -(-(distance_m - BASE_METRES) // 1000)
                fees[area] = BASE_FEE_KES + PER_KM_KES * extra_km
    return fees
```

