def fee_labels(distances_m: list[int]) -> list[str]:
    labels = []
    for dist in distances_m:
        if dist <= BASE_METRES:
            labels.append("150 Kes")
        else:
            extra_km = -(-(dist - BASE_METRES) // 1000)
            labels.append(f"{BASE_FEE_KES} Kes + {PER_KM_KES * extra_km} Kes")
    return labels
```

