def rider_plan(stops_km: list[float], rush_hour: bool) -> int:
    # Delivery helpers
    def calculate_minutes(distance_km: float) -> int:
        # Delivery helpers: 10 minutes per km for normal delivery
        return 10 * distance_km

    total_minutes = 0
    for stop in stops_km:
        total_minutes += calculate_minutes(stop)

    # Rush hour multiplier
    if rush_hour:
        total_minutes *= 1.5

    return int(total_minutes)
```

